// Generated by `just generate` from `src/plugins/claudetto/slices/corrections/lab/corrections.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `corrections` `prompt.submit` hook (gap I02).
// The stubs answer the file reads and the calls of the other slices on a prompt. No model call goes out.
// The file is self-contained, because `just generate` copies it to `tests/` of the plugin, where it cannot import a relative file.

import type { On, PromptOrigin } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

const FILE = ".claudetto/corrections.md";

/** Stubs with the corrections file `text`, or no file when it is `undefined`. Returns the context that each prompt got. */
const setup = (on: On, text?: string) => {
  const contexts: (readonly string[])[] = [];
  mock.env(on, { HOME: "/home/u" });
  on("fs.exists", (_$, e) => ({
    value: e.path.endsWith(FILE) && text !== undefined,
  }));
  on("fs.read", () => ({ value: text ?? "" }));
  on("session.id", () => ({ value: "s-corrections" }));
  on("session.model", () => ({ value: "claude-opus-5-5" }));
  on("settings.read", () => ({ value: {} }));
  on("prompt.submit", (_$, e) => {
    contexts.push(e.context ?? []);
    return { text: e.text };
  });
  return contexts;
};

const submit = ($: Engine, origin: PromptOrigin = { kind: "composer" }) =>
  $.prompt.submit({ text: "Go on.", wait: false, origin });

/** The context of corrections in `context`, or `undefined`. */
const corrections = (context: readonly string[] = []) =>
  context.find((c) => c.includes(FILE));

// biome-ignore lint/plugin: a test name
test("a prompt of the user gets the last items of the corrections file as context", async ($: Engine, on: On) => {
  const items = Array.from({ length: 7 }, (_, i) => `- rule ${i + 1}`);
  const contexts = setup(
    on,
    `# Corrections\n\n${items.join("\n")}\n  more of 7\n`,
  );
  await submit($);
  const text = corrections(contexts[0]);
  expect(text).toContain("- rule 3\n");
  expect(text).toEndWith("- rule 7 more of 7");
  expect(text).not.toContain("rule 2");
});

test("a project with no corrections file adds no context", async ($: Engine, on: On) => {
  const contexts = setup(on);
  await submit($);
  expect(corrections(contexts[0])).toBeUndefined();
});

test("a file with no list item adds no context", async ($: Engine, on: On) => {
  const contexts = setup(on, "Some notes.\n");
  await submit($);
  expect(corrections(contexts[0])).toBeUndefined();
});

test("a prompt that the user did not write gets no corrections", async ($: Engine, on: On) => {
  const contexts = setup(on, "- rule 1\n");
  await submit($, { kind: "task-notification" } as PromptOrigin);
  expect(corrections(contexts[0])).toBeUndefined();
});

test("a long item is cut", async ($: Engine, on: On) => {
  const contexts = setup(on, `- ${"x".repeat(400)}\n`);
  await submit($);
  expect(corrections(contexts[0])).toEndWith(`- ${"x".repeat(300)}...`);
});
